    const base = n.slice(n.lastIndexOf('/') + 1);
    const re = new RegExp('^' + base.replace(/[.+^${}()|[\]]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.') + '$');
    const vus = new Map();
    for (const [k, e] of this.ecrits) vus.set(k, e.taille);
